--
-- Triggers `player`
--
DELIMITER $$
CREATE TRIGGER `set_default_rewards` BEFORE INSERT ON `player` FOR EACH ROW BEGIN
    -- Thiết lập giá trị mặc định cho cột timeReward nếu NULL
    IF NEW.timeReward IS NULL THEN
        SET NEW.timeReward = '[{"isBuy":0,"tookAttendance":0,"timeGive":5},{"isBuy":0,"tookAttendance":0,"timeGive":10},{"isBuy":0,"tookAttendance":0,"timeGive":30},{"isBuy":0,"tookAttendance":0,"timeGive":60},{"isBuy":0,"tookAttendance":0,"timeGive":90},{"isBuy":0,"tookAttendance":0,"timeGive":120},{"isBuy":0,"tookAttendance":0,"timeGive":150},{"isBuy":0,"tookAttendance":0,"timeGive":180},{"isBuy":0,"tookAttendance":0,"timeGive":240},{"isBuy":0,"tookAttendance":0,"timeGive":360}]';
    END IF;

    -- Thiết lập giá trị mặc định cho cột cardReward nếu NULL
    IF NEW.cardReward IS NULL THEN
        SET NEW.cardReward = '[{"isBuy":0,"tookAttendance":0,"card":20000},{"isBuy":0,"tookAttendance":0,"card":50000},{"isBuy":0,"tookAttendance":0,"card":100000},{"isBuy":0,"tookAttendance":0,"card":200000},{"isBuy":0,"tookAttendance":0,"card":500000},{"isBuy":0,"tookAttendance":0,"card":1000000},{"isBuy":0,"tookAttendance":0,"card":2000000},{"isBuy":0,"tookAttendance":0,"card":5000000},{"isBuy":0,"tookAttendance":0,"card":10000000},{"isBuy":0,"tookAttendance":0,"card":20000000}]';
    END IF;

    -- Thiết lập giá trị mặc định cho cột powerReward nếu NULL
    IF NEW.powerReward IS NULL THEN
        SET NEW.powerReward = '[{"isBuy":0,"tookAttendance":0,"card":2},{"isBuy":0,"tookAttendance":0,"card":5},{"isBuy":0,"tookAttendance":0,"card":20},{"isBuy":0,"tookAttendance":0,"card":50},{"isBuy":0,"tookAttendance":0,"card":80},{"isBuy":0,"tookAttendance":0,"card":100},{"isBuy":0,"tookAttendance":0,"card":120},{"isBuy":0,"tookAttendance":0,"card":150},{"isBuy":0,"tookAttendance":0,"card":170},{"isBuy":0,"tookAttendance":0,"card":200},{"isBuy":0,"tookAttendance":0,"card":250}]';
    END IF;
END
$$
DELIMITER ;

