INSERT INTO `task_main_template` (`id`, `NAME`, `detail`) VALUES
(0, 'Nhiệm vụ đầu tiên', 'Chi tiết nhiệm vụ'),
(1, 'Nhiệm vụ tập luyện', 'Mộc nhân được đặt nhiều tại %1, ngay trước nhà ông %2\nHãy đánh ngã 20 mộc nhân, \r\nsau đó quay về nhà báo cáo với ông %2\nĐể đánh, hãy chạm nhanh 2 lần vào đối tượng\nThưởng 5K TVK'),
(2, 'Nhiệm vụ tìm thức ăn', 'Tìm đến %3, tiêu diệt bọn quái %4 và nhặt về 10 đùi gà\nThưởng 5K TVK\nHọc được kỹ năng bay'),
(3, 'Tìm kiếm sao băng', 'Đi khám phá xem vật thể lạ vừa rơi xuống hành tinh\nCuối map vách Kakalot, vách Aru hoặc vách MoriThưởng 3000 sức mạnh\nThưởng 5K TVK'),
(4, 'Nhiệm vụ khó khăn', 'Đi tới %6, tiêu diệt lũ %4 mẹ\nThưởng 5K TVK'),
(5, 'Nhiệm vụ gia tăng sức mạnh', 'Hãy đi tập luyện để gia tăng sức mạnh\nThưởng 5K TVK'),
(6, 'Nhiệm vụ trò chuyện', 'Đi tới trạm tàu vũ trụ, trò chuyện với %7\r\nThưởng 5K TVK'),
(7, 'Nhiệm vụ giải cứu Appule', 'Lên đường tiêu diệt bọn %9, giải cứu %8\nQuay về báo cáo với %2 để nhận thưởng\r\nThưởng 5K TVK'),
(8, 'Nhiệm vụ tiêu diệt quái bay mẹ', 'Tìm và hạ thằn lằn mẹ, phi long mẹ, quỷ bay mẹ\r\nThưởng 5K TVK'),
(9, 'Nhiệm vụ tiên học lễ', 'Tìm đường tới %11, trò chuyện với %10 và xin làm đệ tử\r\nThưởng 5K TVK'),
(10, 'Nhiệm vụ tìm truyện Đôrêmon tập 2', 'Hạ Ốc sên, Heo Xayda mẹ  hoặc Ốc mượn hồn tìm truyện\r\nThưởng 5K TVK'),
(11, 'Nhiệm vụ kết thúc luyện tập', 'Báo cáo cho % để chuẩn bị về nhà\r\nThưởng 5K TVK'),
(12, 'Nhiệm vụ xin phép', 'Quay về nhà xin ông %2 cho phép tham gia bang hội cái bang\r\nThưởng 5K TVK'),
(13, 'Nhiệm vụ gia nhập bang hội', 'Gia nhập 1 bang hội cùng những người đồng đội thiện chí\nCùng làm nhiệm với nhau không quản khó khăn\r\nThưởng 5K TVK'),
(14, 'Nhiệm vụ bang hội lần 1', 'Cùng phối hợp với 1 người đồng đội (hoặc tự đi một mình)  lên đường làm nhiệm vụ\nGợi ý:\nHeo rừng xuất hiện tại rừng Bamboo\nHeo da xanh xuất \r\nhiện tại núi hoa vàng\nHeo xayda xuất hiện tại rừng cọ\r\nThưởng 5K TVK'),
(15, 'Nhiệm vụ bang hội lần 2', 'Hãy cùng 1 người đồng đội bang hội của mình để chiến đấu hết mình nha\r\nThưởng 5K TVK'),
(16, 'Tiêu diệt quái vật', 'Tới các hành tinh tiêu diệt quái vật, giải cứu thường dân\r\nThưởng 5K TVK'),
(17, 'Nhiệm vụ giúp đỡ Cui', 'Tìm đường tới thành phố Vegeta, gặp và nói chuyện với Cui\r\nThưởng 5K TVK'),
(18, 'Nhiệm vụ bất khả thi', 'Tiêu diệt đàn em tay sai của Fide tại Xayda\r\nThưởng 5K TVK'),
(19, 'Nhiệm vụ chạm trán đệ tử', 'Tiêu diệt đàn em tay sai của Fide\r\nThưởng 5K TVK'),
(20, 'Nhiệm vụ Tiểu Đội Sát Thủ', 'Tiêu diệt 5 tên trong đội Tiểu Đội Sát Thủ\r\nThưởng 5K TVK'),
(21, 'Nhiệm vụ chạm trán Fide đại ca', 'Luyện tập đạt 2 tỷ sức mạnh\nLên đường tìm diệt Fide đại ca\r\nThưởng 5K TVK và 1 món thần linh tự chọn'),
(22, 'Nhiệm vụ chạm trán Rôbốt sát thủ lần 1', 'Hãy đến thành phố phía Nam, đảo Balê hoặc Cao nguyên tìm gặp Rôbốt sát thủ để tiêu diệt. Sau đó, hạ 1000 Xên con cấp 1\r\nThưởng 5K TVK'),
(23, 'Nhiệm vụ chạm trán Rôbốt sát thủ lần 2', 'Hãy đến sân sau siêu thị tiêu diệt  bọn Rôbốt sát thủ. Sau đó, cùng 1 thành viên trong bang tiêu diệt Xên con cấp 3\r\nThưởng 5K TVK'),
(24, 'Nhiệm vụ chạm trán Rôbốt sát thủ lần 3', 'Hãy đến thành phố phía Nam, đảo Balê hoặc Cao nguyên tìm gặp Rôbốt sát thủ để tiêu diệt. Sau đó, cùng 1 thành viên trong bang tiêu diệt Xên con cấp 5\r\nThưởng 5K TVK'),
(25, 'Nhiệm vụ giải cứu thị trấn Ginder', 'Hãy đến thị trấn Ginder tìm sinh vật lạ. Sau đó, cùng 1 thành viên trong bang tiêu diệt Xên con cấp 8\r\nThưởng 5K TVK'),
(26, 'Nhiệm vụ thu thập Capsule kỳ bí', 'Mua máy dò tại nhà Bumma và tìm 50 viên Capsule kì bí\r\nThưởng 5K TVK'),
(27, 'Nhiệm vụ tiêu diệt Siêu bọ hung', 'Đến võ đài Siêu bọ hung và tiêu diệt hắn\r\nThưởng 5K TVK'),
(28, 'Nhiệm vụ tiêu diệt Zamasu', 'Tìm và tiêu diệt Black Gôku và Super Zamasu\r\nThưởng 5K TVK'),
(29, 'TIêu diệt Ma bư', 'Tiêu diệt Mabư\r\nThưởng 5K TVK'),
(30, 'Tiêu diệt Cumber', '...'),
(31, 'Đã Hoàn Thành Hết Nhiệm Vụ', 'Vui lòng chờ nhiệm vụ tiếp theo....');
